script:
// Kondenzátor töltése ellenálláson keresztül (RC kör) / Charging a capacitor through a resistor (RC circuit)
//   i = (U − u_C) / R        C · du_C/dt = i        u_C(t) = U · (1 − e^(−t/τ)),  τ = R·C
// Kapcsolási rajz IEC jelekkel: telep (+ hosszú vékony, − rövid vastag), ellenállás = téglalap, kondenzátor = két lemez
// Schematic with IEC symbols: battery (+ long thin, − short thick), resistor = rectangle, capacitor = two plates
stage(1000, 600, "#fbfbf8");
title({hu: "Kondenzátor töltése (RC kör)", en: "Charging a capacitor (RC circuit)"});
param("U", {hu: "Tápfeszültség U", en: "Supply voltage U"}, 1, 24, 12, 0.5, "V");
param("R", {hu: "Ellenállás R", en: "Resistance R"}, 100, 10000, 2000, 100, "Ω");
param("Cap", {hu: "Kapacitás C", en: "Capacitance C"}, 10, 1000, 470, 10, "µF");
toggle("on", {hu: "Kapcsoló zárva", en: "Switch closed"}, true);
button({hu: "Kisütés és újra", en: "Discharge and restart"}, reset);   // a reset elölről indít: u_C = 0 / reset restarts with u_C = 0
plotWindow(10);

let uC = 0;        // a kondenzátor feszültsége (V), ez az állapotváltozó / capacitor voltage (V), the state variable
let posI = 0;      // a mozgó áramnyilak eltolása (px) / offset of the moving current arrows (px)
update(dt => {
  const Cf = P.Cap * 1e-6;                    // µF → F
  const i = P.on ? (P.U - uC) / P.R : 0;      // Ohm törvénye az ellenálláson / Ohm's law on the resistor: i = (U − u_C) / R
  uC += i / Cf * dt;                          // C · du_C/dt = i  →  Δu_C = i/C · Δt
  posI += 40 * i * 1000 * dt;                 // nyilak: 1 mA = 40 px/s, integrálva, így nem ugrálnak / 1 mA = 40 px/s, integrated so they never jump
});

draw(t => {
  const i = P.on ? (P.U - uC) / P.R : 0;
  const tau = P.R * P.Cap * 1e-6;             // időállandó τ = R·C (s) / time constant
  // Vezetékek: minden darab az alkatrész szélénél ér véget / wires: every piece ends at a component's edge
  polyline([[150, 300], [150, 150], [420, 150]], {stroke: C.ink, lw: 3});              // a + lemeztől / from the + plate
  polyline([[580, 150], [800, 150], [800, 270]], {stroke: C.ink, lw: 3});
  polyline([[800, 300], [800, 450], [150, 450], [150, 320]], {stroke: C.ink, lw: 3});  // vissza a − lemezhez / back to the − plate
  // Mozgó nyilak a vezetékdarabokon; ha nincs áram, nem látszanak / moving arrows on the wire pieces; hidden without current
  if (i > 1e-5) for (const w of [[[150, 300], [150, 150], [420, 150]], [[580, 150], [800, 150], [800, 260]], [[800, 310], [800, 450], [150, 450], [150, 320]]])
    flow(w, {pos: posI, dir: 1, color: C.orange, line: false, alpha: clamp(0.3 + i * 1000 / 3, 0, 1)});
  // Alkatrészek felül / components on top
  rect(420, 130, 160, 40, {stroke: C.ink, lw: 3, fill: "#fff"});                        // ellenállás / resistor
  line(740, 270, 860, 270, {stroke: C.ink, lw: 6});                                     // kondenzátor lemezei / capacitor plates
  line(740, 300, 860, 300, {stroke: C.ink, lw: 6});
  line(120, 300, 180, 300, {stroke: C.ink, lw: 3}); line(135, 320, 165, 320, {stroke: C.ink, lw: 7});   // telep / battery
  text("U = " + fmt(P.U, 1) + " V", 110, 316, {size: 18, bold: true, align: "right"});
  text("R", 500, 157, {size: 20, bold: true, align: "center"});
  text("C", 720, 292, {size: 20, bold: true, align: "right"});
  // A töltöttség oszlopa: magassága u_C / U / charge bar: its height is u_C / U
  rect(880, 300 - 100 * uC / P.U, 20, 100 * uC / P.U, {fill: C.blue, stroke: null});
  text("u_C", 878, 330, {size: 16, color: C.blue});
  show({hu: "Kondenzátor feszültsége u_C", en: "Capacitor voltage u_C"}, uC, "V");
  show({hu: "Áram i", en: "Current i"}, i * 1000, "mA");
  show({hu: "Időállandó τ = R·C", en: "Time constant τ = R·C"}, tau, "s");
  show({hu: "Töltöttség u_C / U (τ után 63 %)", en: "Charge u_C / U (63 % after τ)"}, 100 * uC / P.U, "%", 0);
  plot("u_C", uC, {unit: "V", color: C.blue, min: 0});
  plot("i", i * 1000, {unit: "mA", color: C.orange, min: 0});
  val({uC, i});
});
